<script setup>
import { ref, computed, watch, reactive, nextTick } from "vue";
import { useI18n } from "vue-i18n";
import LImg from "@/components/l-img.vue";
import { ApiCharacter } from "@/api/api-character";
import { useUserStore } from '@/store/modules/user';
import { isFormDataIdentical, convertUtcToLocal } from '@/utils/util.js';
import { DATE_FORMATS } from "@/types/date";

const userStore = useUserStore();

const props = defineProps({
  visible: {
    type: Boolean,
    default: false,
  },
  // 新增：快速填写数据prop
  fillData: {
    type: Object,
    default: null,
  },
});

console.log('props', props);

const emit = defineEmits(["update:visible", "cancel", "create"]);

const { t } = useI18n();

// 对话框显示控制
const dialogVisible = ref(false);

// 表单ref
const characterFormRef = ref(null);

// 用于表格的数据
const tableData = ref([
  {
    // 可以在这里添加需要的字段，在联调接口时可直接获取
    row: 1,
  },
]);

// 角色字段映射配置
const CHARACTER_FIELD_MAPPINGS = [
  { current: 'name', original: 'name' },
  { current: 'gender', original: 'gender' },
  { current: 'birthdate', original: ['birthdate', 'age'] },
  { current: 'height', original: 'height' },
  { current: 'weight', original: 'weight' },
  { current: 'nationality', original: 'nationality' },
  { current: 'currentLocation', original: 'currentLocation' },
  { current: 'hometown', original: 'hometown' },
  { current: 'languages', original: 'languages' },
  { current: 'culturalBackground', original: 'culturalBackground' },
  { current: 'education', original: 'education' },
  { current: 'relationshipStatus', original: 'relationshipStatus' },
  { current: 'sensitiveTopics', original: 'sensitiveTopics' },
  { current: 'interests', original: 'interests' },
  { current: 'description', original: 'description' },
  { current: 'prompt', original: 'prompt' }
];

// 监听props.visible变化
watch(
  () => props.visible,
  async (newVal) => {    
    dialogVisible.value = newVal;
    if (newVal) {
      // 弹窗打开时，等待 DOM 更新完成后再填充数据
      await nextTick();
      if (props.fillData) {
        fillFormWithData();
      } else {
        // 如果没有数据，重置表单
        resetForm();
      }
    }
  }
);

// 监听快速填写数据变化
watch(
  () => props.fillData,
  async (newData) => {
    if (newData && dialogVisible.value) {
      // 等待 DOM 更新完成后再填充数据
      await nextTick();
      fillFormWithData();
    }
  },
  { deep: true }
);

// 填充数据到表单（帮助用户快速填写）
const fillFormWithData = () => {
  if (props.fillData) {
    console.log('Filling form with data for quick setup:', props.fillData);
    characterData.value = {
      name: props.fillData.name || "",
      gender: props.fillData.gender || "",
      birthdate: props.fillData.birthdate || props.fillData.age || "",
      height: props.fillData.height || "",
      weight: props.fillData.weight || "",
      nationality: props.fillData.nationality || "",
      currentLocation: props.fillData.currentLocation || "",
      hometown: props.fillData.hometown || "",
      languages: props.fillData.languages || "",
      culturalBackground: props.fillData.culturalBackground || "",
      education: props.fillData.education || "",
      relationshipStatus: props.fillData.relationshipStatus || "",
      sensitiveTopics: props.fillData.sensitiveTopics || "",
      interests: props.fillData.interests || "",
      description: props.fillData.description || "",
      prompt: props.fillData.prompt || "",
    };
    
    // 清除表单验证错误
    if (characterFormRef.value) {
      characterFormRef.value.clearValidate();
    }
  }
};

// 监听dialogVisible变化
watch(
  () => dialogVisible.value,
  (newVal) => {
    emit("update:visible", newVal);
    if (!newVal) {
      // 弹窗关闭时重置表单，但延迟执行避免闪烁
      setTimeout(() => {
        resetForm();
      }, 100);
    }
  }
);

// 角色数据
const characterData = ref({
  name: "",
  gender: "",
  birthdate: "",
  height: "",
  weight: "",
  nationality: "",
  currentLocation: "",
  hometown: "",
  languages: "",
  culturalBackground: "",
  education: "",
  relationshipStatus: "",
  sensitiveTopics: "",
  interests: "",
  description: "",
  prompt: "",
});

// 表单验证规则
const rules = reactive({
  name: [
    {
      required: true,
      message: t("characterName") + " " + t("isRequired"),
      trigger: "blur",
    },
    {
      min: 2,
      max: 50,
      message: "Length should be 2 to 50 characters",
      trigger: "blur",
    },
  ],
  gender: [
    {
      required: true,
      message: t("gender") + " " + t("isRequired"),
      trigger: "change",
    },
  ],
  birthdate: [
    {
      required: true,
      message: t("age") + " " + t("isRequired"),
      trigger: "change",
    },
  ],
  height: [
    {
      required: true,
      message: t("height") + " " + t("isRequired"),
      trigger: "blur",
    },
  ],
  weight: [
    {
      required: true,
      message: t("weight") + " " + t("isRequired"),
      trigger: "blur",
    },
  ],
  nationality: [
    {
      required: true,
      message: t("nationality") + " " + t("isRequired"),
      trigger: "blur",
    },
  ],
  currentLocation: [
    {
      required: true,
      message: t("currentLocation") + " " + t("isRequired"),
      trigger: "blur",
    },
  ],
  hometown: [
    {
      required: true,
      message: t("hometown") + " " + t("isRequired"),
      trigger: "blur",
    },
  ],
  languages: [
    {
      required: true,
      message: t("languages") + " " + t("isRequired"),
      trigger: "blur",
    },
  ],
  culturalBackground: [
    {
      required: true,
      message: t("culturalBackground") + " " + t("isRequired"),
      trigger: "change",
    },
  ],
  education: [
    {
      required: true,
      message: t("education") + " " + t("isRequired"),
      trigger: "change",
    },
  ],
  relationshipStatus: [
    {
      required: true,
      message: t("relationshipStatus") + " " + t("isRequired"),
      trigger: "change",
    },
  ],
  sensitiveTopics: [
    {
      required: true,
      message: t("sensitiveTopics") + " " + t("isRequired"),
      trigger: "blur",
    },
  ],
  interests: [
    {
      required: true,
      message: t("interests") + " " + t("isRequired"),
      trigger: "blur",
    },
  ],
  description: [
    {
      required: true,
      message: t("description") + " " + t("isRequired"),
      trigger: "blur",
    },
    { max: 120, message: t("maxCharacters"), trigger: "blur" },
  ],
  prompt: [
    {
      required: true,
      message: t("characterPrompt") + " " + t("isRequired"),
      trigger: "blur",
    },
  ],
});

// 性别选项
const genderOptions = [
  { value: "genderless", label: t("genderless") },
  { value: "woman", label: t("woman") },
  { value: "man", label: t("man") },
  { value: "non_binary", label: t("nonBinary") },
];

// 文化背景选项
const culturalBackgroundOptions = [
  { value: "asian", label: t("asian") },
  { value: "african", label: t("african") },
  { value: "european", label: t("european") },
  { value: "north_american", label: t("northAmerican") },
  { value: "australian_oceanian", label: t("australianOceanian") },
  { value: "middle_eastern", label: t("middleEastern") },
  { value: "mixed_heritage", label: t("mixedHeritage") },
];

// 教育程度选项
const educationOptions = [
  { value: "high_school_or_below", label: t("highSchool") },
  { value: "associate_degree", label: t("associate") },
  { value: "bachelor_degree", label: t("bachelor") },
  { value: "master_degree", label: t("master") },
  { value: "doctoral_degree", label: t("doctoral") },
  { value: "no_formal_education", label: t("noFormal") },
];

// 感情状态选项
const relationshipStatusOptions = [
  { value: "single", label: t("single") },
  { value: "in_relationship", label: t("inRelationship") },
  { value: "married", label: t("married") },
  { value: "divorced", label: t("divorced") },
  { value: "widowed", label: t("widowed") },
  { value: "complicated", label: t("complicated") }
];

// 关闭弹窗
const handleClose = () => {
  dialogVisible.value = false;
};

// 取消操作
const handleCancel = () => {
  dialogVisible.value = false;
  emit("cancel");
};

// 添加加载状态
const isSubmitting = ref(false);

// 开发环境判断
const isDevelopment = computed(() => import.meta.env.DEV);

// 提交表单
const submitForm = async () => {
  if (!characterFormRef.value) return;

  characterFormRef.value.validate(async (valid) => {
    if (valid) {
      try {
        // 检查是否有快速填写数据，且当前表单数据与快速填写数据完全一致
        if (props.fillData) {
          const isDataIdentical = isFormDataIdentical(
            characterData.value,
            props.fillData,
            CHARACTER_FIELD_MAPPINGS
          );
          
          if (isDataIdentical) {
            ElMessage.warning(t('dataUnchangedError'));
            return;
          }
        }
        
        isSubmitting.value = true;
        const apiData = {
          name: characterData.value.name,
          description: characterData.value.description,
          prompt: characterData.value.prompt,
          gender: characterData.value.gender,
          age: characterData.value.birthdate,
          height: characterData.value.height,
          weight: characterData.value.weight,
          nationality: characterData.value.nationality,
          current_location: characterData.value.currentLocation, // 字段名映射
          hometown: characterData.value.hometown,
          language: characterData.value.languages, // 字段名映射
          cultural_background: characterData.value.culturalBackground, // 字段名映射
          education: characterData.value.education,
          relationship_status: characterData.value.relationshipStatus, // 字段名映射
          sensitive_topics: characterData.value.sensitiveTopics, // 字段名映射
          interests: characterData.value.interests
        };

        // 调用创建角色API
        const response = await ApiCharacter.createCharacter(apiData);

        if (response && response.code === 200) {
          // 创建角色数据对象（用于前端显示）
          const character = {
            id: response.data.id,
            name: response.data.name,
            description: response.data.description,
            prompt: response.data.prompt_preview || characterData.value.prompt,
            author: 'You', // 创建者显示为当前用户
            created_at: convertUtcToLocal(response.data.created_at, DATE_FORMATS.FULL_DATETIME),
            likes: 0, // 新创建的角色默认点赞数为0
            chat_count: response.data.chat_count,
            gender: response.data.gender,
            age: parseInt(response.data.age) || 0, 
            height: response.data.height,
            weight: response.data.weight,
            nationality: response.data.nationality,
            currentLocation: response.data.current_location, // 字段名映射
            hometown: response.data.hometown,
            languages: response.data.language, // 字段名映射
            culturalBackground: response.data.cultural_background, // 字段名映射
            education: response.data.education,
            relationshipStatus: response.data.relationship_status, // 字段名映射
            sensitiveTopics: response.data.sensitive_topics, // 字段名映射
            interests: response.data.interests,
            creator_name: response.data.creator_name
          };

          // 发送创建成功事件
          emit("create", character);

          // 关闭弹窗
          dialogVisible.value = false;

          // 重置表单
          resetForm();

          // 显示成功消息
          ElMessage.success(t("characterCreated"));
        } else {
          console.error(response);
        }
      } catch (error) {
        console.error('Failed to create character:', error);
        handleNetworkError(error);
      } finally {
        isSubmitting.value = false;
      }
    }
  });
};

// 重置表单
const resetForm = () => {
  characterData.value = {
    name: "",
    gender: "",
    birthdate: "",
    height: "",
    weight: "",
    nationality: "",
    currentLocation: "",
    hometown: "",
    languages: "",
    culturalBackground: "",
    education: "",
    relationshipStatus: "",
    sensitiveTopics: "",
    interests: "",
    description: "",
    prompt: "",
  };

  if (characterFormRef.value) {
    characterFormRef.value.resetFields();
    characterFormRef.value.clearValidate();
  }
};

const handleNetworkError = (error) => {
  if (error.name === 'NetworkError' || error.message.includes('fetch')) {
    ElMessage.error(t('networkError'));
  } else if (error.name === 'TimeoutError') {
    ElMessage.error(t('timeoutError'));
  } else {
    ElMessage.error(error.message || t('createError'));
  }
};

