<template>
  <div v-loading="showMessageAreaLoading" class="character-message-list-container">
    <!-- 消息列表区域 -->
    <div ref="msgListRef" class="msg-list" @scroll="handleScroll">
      <div v-if="loadingType == 'more'" class="loading-more">
        <div class="loading-spinner"></div>
        <span>{{ t('loading') }}</span>
      </div>
      <!-- 消息列表 -->
      <div v-for="item in msgList" :key="item.id" class="message-wrapper">
        <character-message-item :content="item.content" :role="item.role" :timestamp="item.created_at || item.timestamp"
          :isMarkdown="item.isMarkdown" :typing="item.typing" :isAiThinking="item.isAiThinking"
          :message-status="item.messageStatus" :message-id="item.id" @onRetry="handleRetryMessage" />
      </div>
      <!-- 底部占位元素，用于滚动定位 -->
      <div ref="lastMsgRef" class="scroll-anchor"></div>
    </div>

    <!-- 消息输入区域 -->
    <div v-if="currentModel" class="character-message-input-container">
        <div class="input-wrapper">
            <textarea ref="textareaRef" v-model="inputText" :placeholder="t('typeYourMessage')" class="message-textarea"
                @keydown="handleKeydown" @input="adjustHeight" @compositionstart="handleCompositionStart"
                @compositionend="handleCompositionEnd" rows="1"></textarea>
            <div class="input-footer">
                <l-dropdown
                    ref="modelDropdownRef"
                    :type="MODEL_CAPABILITIES.TEXT"
                    :initialSelected="currentModel"
                    @update:selected="onModelSelected"
                    trigger="click"
                >
                    <div class="chooise-action">
                        <span>{{ currentModel }}</span>
                    </div>
                </l-dropdown>
                <div class="send-button" :disabled="!canSend" @click="handleSend">
                                    <l-img  v-if="!canSend" w="30px" h="30px" src="/static/images/image_chat/send_button.png" />
                <l-img v-else w="30px" h="30px" src="/static/images/image_chat/send_active_session.png" />
                </div>
            </div>
        </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onUnmounted, nextTick, watch, computed, onMounted } from 'vue';
 import { useI18n } from 'vue-i18n';
import { ElMessage } from 'element-plus';
 import CharacterMessageItem from '@/components/ai-chat-tool/character-message-item.vue';
import LDropdown from '@/components/l-dropdown.vue';
import LImg from '@/components/l-img.vue';
import { pxToRem } from '@/utils/px-to-rem';
import { ApiCharacter } from '@/api/api-character';
import { MSG_ROLE_USER, MSG_ROLE_ASSISTANT, MESSAGE_STATUS } from '@/types/msg';
import { MODEL_CAPABILITIES } from '@/models/chat-model-models';

const { t } = useI18n();

const props = defineProps({
    selectedSession: {
    type: Object,
    default: null
  },
  character: {
    type: Object,
    default: null
  },
  currentModel: {
    type: String,
    default: ''
  }
});

const emit = defineEmits(['onLoadComplete', 'onSendMessage', 'onSessionCreate', 'onModelSelected']);

// 消息列表相关的响应式数据
const msgList = ref([]);
const msgListRef = ref(null);
const lastMsgRef = ref(null);
const inputDisabled = ref(false);
const isLoading = ref(false);
const loadingType = ref('none');
const hasMore = ref(true);
const cursor = ref(null);
const autoScroll = ref(true);
const lastScrollTop = ref(0);
const pageSize = ref(20);
const isAiThinking = ref(false);
const modelDropdownRef = ref(null);
const maintainScrollPosition = ref(false);

// 输入框相关的响应式数据
const inputText = ref('');
const textareaRef = ref(null);
// 输入法组合状态标志
const isComposing = ref(false);

const showMessageAreaLoading = computed(() => {
    return !props.selectedSession?.isNew && loadingType.value == 'initial'
});

// 输入框相关的计算属性
const canSend = computed(() => {
    return inputText.value.trim().length > 0 && !inputDisabled.value;
});

// 创建消息对象的辅助函数
const createMessage = (content, role, additionalData = {}) => {
    const currentTime = new Date().toISOString();
    return {
        id: additionalData.id || Date.now(),
        content: content.trim(),
        role,
        created_at: additionalData.created_at || currentTime,
        isMarkdown: role === MSG_ROLE_ASSISTANT,
        typing: false,
        isAiThinking: false,
        messageStatus: additionalData.messageStatus || MESSAGE_STATUS.SUCCESS, // 默认为成功状态
        ...additionalData
    };
};

// 获取会话ID的辅助函数
const getSessionId = () => {
    const sessionId = props.selectedSession?.id;
    // 如果会话ID长度为13，说明是临时会话，返回null
    return sessionId?.length === 13 ? null : sessionId;
};

// 输入框方法
const handleSend = () => {
    if (!canSend.value) return;

    const message = inputText.value.trim();
    if (message) {
        // 发送消息和当前选择的模型
        handleSendMessage({
            content: message,
            model: props.currentModel
        });
        inputText.value = '';
        adjustHeight();
    }
};

// 新的模型选择事件处理
const onModelSelected = (modelName) => {
  emit('onModelSelected', modelName);
};

// 处理输入法组合开始事件
const handleCompositionStart = () => {
    isComposing.value = true;
};

// 处理输入法组合结束事件
const handleCompositionEnd = () => {
    isComposing.value = false;
};

const handleKeydown = (event) => {
    // 如果正在输入法组合状态（如中文拼音输入），不处理回车键
    if (isComposing.value) {
        return;
    }

    // Ctrl/Cmd + Enter 发送消息
    if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') {
        event.preventDefault();
        handleSend();
    }
    // 阻止单独的 Enter 键换行，如果需要换行可以使用 Shift + Enter
    else if (event.key === 'Enter' && !event.shiftKey) {
        event.preventDefault();
        handleSend();
    }
};

const adjustHeight = () => {
    nextTick(() => {
        if (textareaRef.value) {
            textareaRef.value.style.height = 'auto';
            const scrollHeight = textareaRef.value.scrollHeight;
            const maxHeight = 120; // 最大高度约6行
            textareaRef.value.style.height = pxToRem(Math.min(scrollHeight, maxHeight));
        }
    });
};

// 处理发送消息
const handleSendMessage = async (messageData) => {
    const { content, model } = messageData;

    // 输入验证
    if (!props.selectedSession?.id || !content?.trim()) {
        console.warn('Session ID or content is missing');
        return;
    }

    if (!props.character?.id) {
        console.warn('Character ID is missing');
        return;
    }

    let userMessage = null;
    let thinkingMessage = null;

  try {
    inputDisabled.value = true;
      isAiThinking.value = true;
        // 创建用户消息
        userMessage = createMessage(content, MSG_ROLE_USER);

        // 添加用户消息到列表
        addMessage(userMessage);

        // 创建AI思考中消息
        thinkingMessage = createMessage('', MSG_ROLE_ASSISTANT, {
            id: 'thinking-' + Date.now(),
            isAiThinking: true,
            messageStatus: MESSAGE_STATUS.SENDING,
            originalParams: {
                content: content.trim(),
                model: model,
                sessionId: props.selectedSession?.id?.length != 13 ? props.selectedSession?.id : null,
                characterId: props.character?.id
            }
        });

        // 添加AI思考消息到列表
        addMessage(thinkingMessage);

        // 触发消息更新事件
        emit('onSessionCreate', {
            sessionId: props.selectedSession.id,
            lastMessage: userMessage.content,
            lastMessageTime: userMessage.created_at
        });

        emit('onMessageUpdateNum', {
            sessionId: props.selectedSession.id,
            num: 1
        });

        // 发送消息到服务器
        const response = await ApiCharacter.sendCharacterMessage(
            props.character.id,
            userMessage.content,
            model,
            getSessionId()
        );

        // 移除思考中消息
        if (thinkingMessage?.id) {
            msgList.value = msgList.value.filter(msg => msg.id !== thinkingMessage.id);
        }

        // 处理API响应
        if (response?.data) {
            // 创建AI回复消息
            const aiMessage = createMessage(
                response.data.content,
                MSG_ROLE_ASSISTANT,
                {
                    id: response.data.id,
                    created_at: response.data.created_at
                }
            );
            // 添加AI消息到列表
            addMessage(aiMessage, false);
            // 检查是否是新会话创建（临时会话转换为真实会话）
            const isNewSession = response.data.session_id &&
                (!props.selectedSession.id || props.selectedSession.id !== response.data.session_id);

            // 触发AI消息更新事件
            emit('onSessionCreate', {
                sessionId: response.data.session_id || props.selectedSession.id,
                lastMessage: aiMessage.content,
                lastMessageTime: aiMessage.created_at,
                isAi: true,
                isNewSession
            });
            emit('onMessageUpdateNum', {
                sessionId: response.data.session_id || props.selectedSession.id,
                num: 1
            });
        } else {
            throw new Error('Invalid API response');
        }

    } catch (error) {
        console.error('Failed to send message:', error);

        // 移除思考中消息
        if (thinkingMessage?.id) {
            msgList.value = msgList.value.filter(msg => msg.id !== thinkingMessage.id);
        }

        // 显示错误提示
        ElMessage.error(t("failedToSendMessage"));

        // 创建失败状态的AI消息
        const failedAiMessage = createMessage('', MSG_ROLE_ASSISTANT, {
            id: 'failed-' + Date.now(),
            messageStatus: MESSAGE_STATUS.FAILED,
            originalParams: {
                content: content.trim(),
                model: model,
                sessionId: getSessionId(),
                characterId: props.character?.id
            }
        });
        
        // 添加失败消息到列表
        addMessage(failedAiMessage);

    } finally {
        // 始终重新启用输入和重置思考状态
        inputDisabled.value = false;
        isAiThinking.value = false;
    }
};

// 新增：处理消息重试
const handleRetryMessage = async (messageId) => {
    const messageIndex = msgList.value.findIndex(msg => msg.id === messageId);
    if (messageIndex === -1) return;
    
    const message = msgList.value[messageIndex];
    if (!message.originalParams || message.role !== MSG_ROLE_ASSISTANT) return;
    
    let thinkingMessage = null;
    
    try {
        inputDisabled.value = true;
        isAiThinking.value = true;
        
        // 移除失败的消息
        msgList.value.splice(messageIndex, 1);
        
        // 创建新的思考中消息
        thinkingMessage = createMessage('', MSG_ROLE_ASSISTANT, {
            id: 'thinking-retry-' + Date.now(),
            isAiThinking: true,
            messageStatus: MESSAGE_STATUS.SENDING,
            originalParams: message.originalParams
        });
        
        // 添加思考消息到列表
        addMessage(thinkingMessage);
        
        // 重新发送消息
        const response = await ApiCharacter.sendCharacterMessage(
            message.originalParams.characterId,
            message.originalParams.content,
            message.originalParams.model,
            message.originalParams.sessionId
        );
        
        // 移除思考中消息
        if (thinkingMessage?.id) {
            msgList.value = msgList.value.filter(msg => msg.id !== thinkingMessage.id);
        }
        
        if (response?.data) {
            // 创建成功的AI回复消息
            const aiMessage = createMessage(
                response.data.content,
                MSG_ROLE_ASSISTANT,
                {
                    id: response.data.id,
                    created_at: response.data.created_at
                }
            );
            
            // 添加AI消息到列表
            addMessage(aiMessage, false);
            
            emit('onSessionCreate', {
                sessionId: response.data.session_id || message.originalParams.sessionId,
                lastMessage: aiMessage.content,
                lastMessageTime: aiMessage.created_at,
                isAi: true
            });
        } else {
            throw new Error('Invalid API response');
        }
    } catch (error) {
        console.error('Failed to retry message:', error);
        
        // 移除思考中消息
        if (thinkingMessage?.id) {
            msgList.value = msgList.value.filter(msg => msg.id !== thinkingMessage.id);
        }
        
        // 显示错误提示
        ElMessage.error(t("failedToSendMessage"));
        
        // 创建新的失败状态消息
        const failedAiMessage = createMessage('', MSG_ROLE_ASSISTANT, {
            id: 'failed-retry-' + Date.now(),
            messageStatus: MESSAGE_STATUS.FAILED,
            originalParams: message.originalParams
        });
        
        // 添加失败消息到列表
        addMessage(failedAiMessage);
        
    } finally {
        inputDisabled.value = false;
        isAiThinking.value = false;
    }
};

// 防抖定时器
let scrollTimer = null;

// 滚动处理
const handleScroll = (e) => {
  // 如果正在维护滚动位置，暂时忽略滚动事件
  if (maintainScrollPosition.value) {
    return;
  }

  const el = e.target;
  const currentScrollTop = el.scrollTop;
  const scrollHeight = el.scrollHeight;
  const clientHeight = el.clientHeight;

  // 计算滚动方向
  const isScrollingUp = currentScrollTop < lastScrollTop.value;

  // 判断是否滚动到底部（允许5px的误差）
  const isAtBottom = scrollHeight - (currentScrollTop + clientHeight) < 5;

  // 如果用户滚动到底部，恢复自动滚动
  if (isAtBottom) {
    autoScroll.value = true;
  }
  // 如果用户向上滚动，关闭自动滚动
  else if (isScrollingUp) {
    autoScroll.value = false;
  }

  // 防抖处理加载更多逻辑
  if (scrollTimer) {
    clearTimeout(scrollTimer);
  }

  scrollTimer = setTimeout(() => {
    // 检查是否需要加载更多（更精确的判断）
    const SCROLL_THRESHOLD = 100;
    if (isScrollingUp &&
        currentScrollTop <= SCROLL_THRESHOLD &&
        !isLoading.value &&
        hasMore.value &&
        msgList.value.length > 0 &&
        !maintainScrollPosition.value) {
      loadMoreMessages();
    }
  }, 150); // 增加防抖时间到150ms

  if (!isLoading.value && !maintainScrollPosition.value) {
    lastScrollTop.value = currentScrollTop;
  }
};

// 加载消息列表
const loadMessages = async (isInitial = false) => {
  if (isInitial) {
    cursor.value = null;
  } else if (isLoading.value || !hasMore.value) {
    return;
  }

  // 记录加载前的滚动状态（用于防止抖动）
  let scrollState = null;
  if (!isInitial && msgListRef.value) {
    scrollState = {
      scrollTop: msgListRef.value.scrollTop,
      scrollHeight: msgListRef.value.scrollHeight,
      clientHeight: msgListRef.value.clientHeight
    };
  }

  isLoading.value = true;
  loadingType.value = isInitial ? 'initial' : 'more';

  try {
    if (!props.selectedSession?.id) {
      isLoading.value = false;
      loadingType.value = 'none';
      return;
    }

    const res = await ApiCharacter.getCharacterChatMessageList(
      props.selectedSession?.id,
      pageSize.value,
      cursor.value || null
    );

    if (res.data && Array.isArray(res.data.items) && res.data.items.length > 0) {
      const newMessages = res.data.items.reverse().map(item => ({
        id: item.id,
        content: item.content,
        role: item.role,
        created_at: item.created_at,
        isMarkdown: item.role === MSG_ROLE_ASSISTANT,
        typing: false,
        messageStatus: MESSAGE_STATUS.SUCCESS // 历史消息默认为成功状态
      }));

      if (isInitial) {
        msgList.value = newMessages;
      } else {
        maintainScrollPosition.value = true;
        msgList.value = [...newMessages, ...msgList.value];
        await nextTick();
        if (scrollState && msgListRef.value) {
          const newScrollHeight = msgListRef.value.scrollHeight;
          const heightDifference = newScrollHeight - scrollState.scrollHeight;
          if (heightDifference > 0) {
            requestAnimationFrame(() => {
              if (msgListRef.value) {
                msgListRef.value.scrollTop = scrollState.scrollTop + heightDifference;
                maintainScrollPosition.value = false;
              }
            });
          } else {
            maintainScrollPosition.value = false;
          }
        } else {
          maintainScrollPosition.value = false;
        }
      }

      hasMore.value = res.data.has_more;
      if (res.data.items.length > 0 && hasMore.value) {
        cursor.value = res.data.items[0].id;
      } else {
        cursor.value = null;
      }

      if (isInitial) {
        nextTick(() => {
          scrollToBottom();
        });
      }

      emit('onLoadComplete', msgList.value);
    } else {
      hasMore.value = false;
      cursor.value = null;
      if (isInitial) {
        msgList.value = [];
        emit('onLoadComplete', msgList.value);
      }
    }
  } catch (error) {
    console.error('Failed to load messages:', error);

    // 如果是初始加载且API失败，使用模拟数据
    if (isInitial) {
      const mockMessages = [];

      msgList.value = mockMessages;
      hasMore.value = false;

      nextTick(() => {
        scrollToBottom();
      });

      emit('onLoadComplete', msgList.value);
    }
  } finally {
    setTimeout(() => {
      isLoading.value = false;
      loadingType.value = 'none';
    }, 300);
  }
};

// 加载更多消息
const loadMoreMessages = () => {
  // 防止重复触发
  if (isLoading.value || !hasMore.value) {
    return;
  }
  loadMessages(false);
};

// 滚动到底部
const scrollToBottom = () => {
  if (!autoScroll.value) return;

  nextTick(() => {
    if (msgListRef.value) {
      msgListRef.value.scrollTop = msgListRef.value.scrollHeight;
    }
  });
};

// 添加新消息到列表
const addMessage = (message, isAutoScroll = true) => {
  msgList.value.push(message);
  autoScroll.value = isAutoScroll;
  nextTick(() => {
    scrollToBottom();
  });
};

watch(() => props.selectedSession?.id, async (newSessionId) => {
  // 监听会话ID变化，当ID存在且长度不为13时重新加载消息
  console.log('Session ID changed:', newSessionId);
  if (newSessionId && newSessionId.length != 13) {
    loadMessages(true);
  } else if (newSessionId && newSessionId.length == 13) {
    msgList.value = [];
  }
  inputText.value = '';
  await nextTick();
  modelDropdownRef?.value?.handleSelectItem(props.selectedSession.ai_model);
}, { immediate: true, deep: true });

// 生命周期
onMounted(() => {
    adjustHeight();
});

// 组件卸载时清理定时器
onUnmounted(() => {
  if (scrollTimer) {
    clearTimeout(scrollTimer);
    scrollTimer = null;
  }
});

// 对外暴露方法
defineExpose({
  addMessage,
  loadMessages,
  msgList,
  focus: () => {
        if (textareaRef.value) {
            textareaRef.value.focus();
        }
    },
    clear: () => {
        inputText.value = '';
        adjustHeight();
    }
});
</script>

