<template>
    <div class="message-area">
        <!-- 空状态 -->
        <div v-if="!selectedSession" class="empty-state">
            <p class="empty-text">{{ t('selectChatToViewMessages') }}</p>
        </div>

        <!-- 消息容器 -->
        <div v-else class="message-container">
            <!-- 会话信息头部 -->
            <SessionHeader :session="sessionForHeader" :character="selectedCharacter" :format-date-only="formatDateOnly"
                @share="handleShare" @show-details="handleShowDetails" />

            <!-- 消息列表区域 -->
            <div class="messages-content">
                <CharacterMessageList :selectedSession="selectedSession" :character="selectedCharacter"
                    :currentModel="currentModel" @onSessionCreate="handleSessionCreate"
                    @onModelSelected="handleModelSelected" @onMessageUpdateNum="handleMessageUpdateNum" />
            </div>
        </div>
    </div>
</template>

<script setup>
import { useI18n } from 'vue-i18n';
import { computed } from 'vue';
import CharacterMessageList from '@/components/ai-chat-tool/character-message-list.vue';
import SessionHeader from '@/components/ai-chat-tool/session-header.vue';

const { t } = useI18n();

// Props 定义
const props = defineProps({
    selectedSession: {
        type: Object,
        default: null
    },
    selectedCharacter: {
        type: Object,
        default: null
    },
    formatDateOnly: {
        type: Function,
        required: true
    },
    currentModel: {
        type: String,
        default: ''
    }
});

// 为SessionHeader组件准备的会话数据
const sessionForHeader = computed(() => {
    if (!props.selectedSession || !props.selectedCharacter) return null;

    return {
        title: `${props.selectedCharacter.title} - ${t('chatWithName', { name: props.selectedSession.user_name || '' })}`,
        last_message_time: new Date().toISOString(), // 使用当前时间作为开始时间
        remark: props.selectedSession.remark
    };
});

// Emits 定义
const emit = defineEmits([
    'share-session',
    'show-character-details', 
    'session-create',
    'model-selected',
    'message-update-num'
]);

// 事件处理函数
const handleShare = (session) => {
    emit('share-session', session);
};

const handleShowDetails = (character) => {
    emit('show-character-details', character);
};

const handleSessionCreate = (messageData) => {
    emit('session-create', messageData);
};

const handleModelSelected = (modelName) => {
    emit('model-selected', modelName);
};

const handleMessageUpdateNum = (messageData) => {
  console.log('handleMessageUpdateNum', messageData);
    emit('message-update-num', messageData);
};
</script>

