<template>
    <div class="character-list-page" :style="pageStyle">
        <!-- 左侧角色列表 -->
        <CharacterSidebar :title="t('characterList')" :selected-item="selectedCharacter"
            @select="handleCharacterSelect" @create="handleCreateCharacter" @show-details="handleShowCharacterDetails"
            ref="characterSidebarRef" />

        <!-- 第一个分割线 -->
        <ResizableDivider 
            divider-type="first"
            :left-min-width="200" 
            :left-max-width="600"
            :right-min-width="200" 
            :right-max-width="600"
            @resize="handleFirstDividerResize" 
        />

        <!-- 中间聊天记录列表 -->
        <ChatSidebar :selected-character="selectedCharacter" :selected-session="selectedSession"
            :chat-sessions="chatSessions" :pagination="sessionPagination" :modelType="MODEL_CAPABILITIES.TEXT"
            @select-session="handleSessionSelect" @create-new-chat="handleCreateNewChat" @edit-remark="handleEditRemark"
            @share-session="handleShareSession" @delete-session="handleDeleteSession" @scroll="handleSessionScroll" 
            @filter-change="handleFilterChange" />

        <!-- 第二个分割线 -->
        <ResizableDivider 
            divider-type="second"
            :left-min-width="200" 
            :left-max-width="600"
            :right-min-width="200" 
            :right-max-width="600"
            @resize="handleSecondDividerResize" 
        />

        <!-- 右侧消息详情区域 -->
        <MessageDetailCharacter 
            ref="messageDetailCharacterRef"
            :selected-session="selectedSession"
            :selected-character="selectedCharacter"
            :format-date-only="formatDateOnly"
            :currentModel="currentModel"
            @share-session="handleShareSession"
            @show-character-details="handleShowCharacterDetails"
            @session-create="handleSessionCreate"
            @model-selected="handleModelSelected"
            @message-update-num="handleMessageUpdateNum"
        />

        <!-- 创建角色弹层 -->
        <div v-show="isCreateCharacterDialogVisible" class="create-character-dialog-container">
            <CreateCharacter 
                :visible="isCreateCharacterDialogVisible"
                :fill-data="quickFillCharacterData"
                @update:visible="isCreateCharacterDialogVisible = $event" 
                @create="handleCreateSuccess" 
            />
        </div>

        <!-- 角色详情查看弹层 -->
        <div v-show="isPromptViewDialogVisible" class="prompt-view-dialog-container">
            <PromptView 
                :visible="isPromptViewDialogVisible" 
                @update:visible="isPromptViewDialogVisible = $event"
                :prompt="currentPromptData" 
                :detail-data="characterDetailData"
                :loading="isLoadingCharacterDetail"
                @load-detail="handleLoadCharacterDetail"
                @delete="handleCharacterDelete"
                @edit="handleEdit"
            />
        </div>

        <!-- 备注弹窗 -->
        <div v-show="isRemarkDialogVisible" class="remark-dialog-container">
            <RemarkDialog v-model:visible="isRemarkDialogVisible" :initial-value="currentEditingSession?.remark || ''"
                @save="handleRemarkConfirm" @cancel="handleRemarkCancel" />
        </div>

        <!-- 删除确认弹窗 -->
        <SessionDeleteDialog v-model:visible="deleteDialogVisible" :session="sessionToDelete" @confirm="confirmDelete" />
    </div>
</template>

<script setup>
import { ref, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import { useRouter } from 'vue-router'; 
import { ElMessage } from 'element-plus';

// 组件导入
import CharacterSidebar from '@/components/ai-chat-tool/character-sidebar.vue';
import ChatSidebar from '@/components/ai-chat-tool/chat-sidebar.vue';
import MessageDetailCharacter from '@/components/ai-chat-tool/message-detail-character.vue';
import CreateCharacter from '@/components/ai-chat-tool/create-character.vue';
import PromptView from '@/components/dialog/prompt-view.vue';
import RemarkDialog from '@/components/dialog/remark-dialog.vue';
import SessionDeleteDialog from '@/components/dialog/session-delete-dialog.vue';
import ResizableDivider from '@/components/business/resizable-divider.vue';

// 组合式函数导入
import { useCharacterList } from '@/composables/useCharacterList';
import { useResizablePanels } from '@/composables/useResizablePanels';

// API导入
import { ApiCharacter } from '@/api/api-character';
import { useUserStore } from '@/store/modules/user';
import { MODEL_CAPABILITIES } from '@/models/chat-model-models';
import { validateAndSetAIModel } from '@/utils/ai-model-validator';

const { t } = useI18n();
const userStore = useUserStore();

// 响应式数据
const currentModel = ref('');
const selectedCharacter = ref(null);
const selectedSession = ref(null);
const currentPromptData = ref(null);
const currentEditingSession = ref(null);
const sessionToDelete = ref(null);
const characterSidebarRef = ref(null);
 
// 弹层控制状态
const isCreateCharacterDialogVisible = ref(false);
const isPromptViewDialogVisible = ref(false);
const isRemarkDialogVisible = ref(false);
const deleteDialogVisible = ref(false);

// 新增：角色详情数据加载相关状态
const characterDetailData = ref(null);
const isLoadingCharacterDetail = ref(false);

// 新增：快速填写角色数据状态
const quickFillCharacterData = ref(null);

// 使用拖拽面板功能
const {
    leftPanelWidth: characterSidebarWidth,
    rightPanelWidth: chatSidebarWidth,
    pageStyle,
    handleFirstDividerResize,
    handleSecondDividerResize
} = useResizablePanels({
    leftPanel: {
        defaultPercent: 20,
        defaultPixels: 300, // 默认300px宽度
        minPixels: 200,
        maxPixels: 600
    },
    rightPanel: {
        defaultPercent: 20,
        defaultPixels: 300, // 默认300px宽度
        minPixels: 200,
        maxPixels: 600
    },
    storageKey: 'character-list-panels'
});

// 使用组合式函数
const { formatCharacterDetails, formatDateOnly } = useCharacterList();
const filterParams = ref({
    model: null,
});

// 模拟会话数据
const mockSessions = [];

// 会话数据管理
const chatSessions = ref([]);
const sessionPagination = ref({
    cursor: null,
    hasMore: false,
    pageSize: 20,
    loading: true
});


// 监听创建弹窗状态变化，弹窗关闭时清除快速填写数据
watch(isCreateCharacterDialogVisible, (isVisible) => {
    if (!isVisible) {
        quickFillCharacterData.value = null;
    }
});

// 加载聊天会话列表
const loadChatSessions = async(isInit = true) => {
    if (!selectedCharacter.value) return;
    
    try {
        if (isInit) {
            sessionPagination.value.loading = true;
            sessionPagination.value.cursor = null;
            sessionPagination.value.hasMore = false;
        } else { 
            sessionPagination.value.loading = true;
        }

        const response = await ApiCharacter.getCharacterSessionList(
            selectedCharacter.value.id,
            sessionPagination.value.pageSize,
            sessionPagination.value.cursor,
            filterParams.value.model || null
        );

        if (response && response.code === 200 && response.data) {
            const newItems = response.data.items || [];

            if (!isInit) {
                // 加载更多时追加数据
                chatSessions.value.push(...newItems);
            } else {
                // 首次加载时替换数据
                chatSessions.value = newItems;
            }

            // 更新分页状态
            sessionPagination.value.hasMore = response.data.has_more || false;
            if (newItems.length > 0) {
                sessionPagination.value.cursor = newItems[newItems.length - 1].id;
            }
        } else {
            throw new Error('API response error');
        }
    } catch (error) {
        if (isInit) {
            // 只在首次加载失败时使用模拟数据作为后备
            chatSessions.value = mockSessions;
            sessionPagination.value.hasMore = false;
        }

        ElMessage.warning(t('loadError') || 'Failed to load chat sessions');
    } finally {
        if (!isInit) {
            sessionPagination.value.loading = false;
        } else {
            sessionPagination.value.loading = false;
        }
    }
};

// 添加新会话到列表顶部
const addChatSession = (newSession) => {
    chatSessions.value.unshift(newSession);
};

// 从列表中移除会话
const removeChatSession = (sessionId) => {
    const index = chatSessions.value.findIndex(session => session.id === sessionId);
    if (index > -1) {
        chatSessions.value.splice(index, 1);
    }
};

// 更新列表中的会话
const updateChatSession = (sessionId, updates) => {
  console.log('updateChatSession', sessionId, updates);
    const index = chatSessions.value.findIndex(session => session.id === sessionId);
    if (index > -1) {
        chatSessions.value[index] = { ...chatSessions.value[index], ...updates };
    }
};

// 重置会话状态
const resetSessions = () => {
    chatSessions.value = [];
    sessionPagination.value.cursor = null;
    sessionPagination.value.hasMore = false;
    sessionPagination.value.loading = true;
};

// 角色选择处理
const handleCharacterSelect = async (character) => {
    if(selectedCharacter.value?.id === character.id) return;
    selectedCharacter.value = character;
    selectedSession.value = null;
    resetSessions();
    
    if (character) {
        try {
            await loadChatSessions(true);
        } catch (error) {
            ElMessage.warning(t('loadError'));
        }
    }
};

// 会话选择处理
const handleSessionSelect = async (session) => {
    selectedSession.value = session;
    await validateAndSetAIModel({
        sessionModel: session.ai_model,
        modelType: 'text',
        currentModelRef: currentModel
    });
};

// 创建角色处理
const handleCreateCharacter = () => {
    isCreateCharacterDialogVisible.value = true;
};

// 创建新聊天处理
const handleCreateNewChat = async (modelName) => {
    if (!selectedCharacter.value) return;
    
    const userName = userStore.userInfo?.nickname || '';
    const newSession = {
        id: String(Date.now()), // 确保ID是字符串类型
        title: userName,
        user_name: userName,
        last_message_content: '',
        last_message_time: new Date().toISOString(),
        remark: '',
        is_pinned: false,
        message_count: 0,
        isNew: true // 标记为临时会话
    };
    if (modelName) {
        newSession.ai_model = modelName;
        currentModel.value = modelName;
    }

    addChatSession(newSession);
    selectedSession.value = newSession;
    
    ElMessage.success(t('chatCreated'));
};

// 编辑备注处理
const handleEditRemark = (session) => {
    currentEditingSession.value = session;
    isRemarkDialogVisible.value = true;
};

// 分享会话处理
const handleShareSession = (session) => {
    ElMessage.info(t('shareFeatureComingSoon'));
};

// 删除会话处理
const handleDeleteSession = (session) => {
    sessionToDelete.value = session;
    deleteDialogVisible.value = true;
};

// 会话滚动处理 - 现在由 list-more 组件处理
const handleSessionScroll = (event) => {
    // 检查是否需要加载更多数据
    if (selectedCharacter.value) {
        const { scrollTop, scrollHeight, clientHeight } = event.target;
        const threshold = 50;
        
        if (scrollHeight - scrollTop - clientHeight < threshold && 
            sessionPagination.value.hasMore &&
            !sessionPagination.value.loading) {
            loadChatSessions(false);
        }
    }
};

// 显示角色详情
const handleShowCharacterDetails = (character) => {
    // 传递完整的角色数据，包括 ID，并格式化为 prompt 结构
    currentPromptData.value = {
        id: character.id,
        title: t("characterDetails"),
        name: character.name,
        category: character.name,
        description: character.description,
        content: character.prompt_preview || character.prompt || '',
        prompt: character.prompt_preview || character.prompt || '',
        creator: character.creator_name || 'Unknown',
        creator_name: character.creator_name,
        createdAt: character.created_at,
        created_at: character.created_at,
        chats: character.chat_count || 0,
        chat_count: character.chat_count || 0,
        // 包含角色的所有详细信息
        gender: character.gender,
        age: character.age,
        // 保持原有的 characterDetails 结构以兼容
        characterDetails: formatCharacterDetails(character).characterDetails
    };
    
    // 重置详情数据状态
    characterDetailData.value = null;
    isLoadingCharacterDetail.value = false;
    
    isPromptViewDialogVisible.value = true;
};

// 新增：处理角色详情数据加载
const handleLoadCharacterDetail = async (characterId) => {
    if (!characterId) {
        console.warn('No character ID provided for detail loading');
        return;
    }

    isLoadingCharacterDetail.value = true;

    try {
        const response = await ApiCharacter.getCharacterDetail(characterId);

        if (response && response.code === 200 && response.data) {
            characterDetailData.value = response.data;
        } else {
            console.warn('Failed to load character detail:', response);
            ElMessage.warning(t('loadError'));
        }
    } catch (error) {
        console.error('Error loading character detail:', error);
        ElMessage.error(t('loadError'));
    } finally {
        isLoadingCharacterDetail.value = false;
    }
};

// 角色删除处理
const handleCharacterDelete = async (promptData) => {    
    try {
        // 直接使用传递的角色数据中的 ID
        const characterId = promptData.id;
        if (!characterId) {
            ElMessage.error(t('deleteError'));
            return;
        }

        const response = await ApiCharacter.deleteCharacter(characterId);
        
        if (response && response.code === 200) {
            // 从角色列表中移除
            characterSidebarRef.value?.removeCharacter(characterId);
            
            // 如果删除的是当前选中的角色，清空选择
            if (selectedCharacter.value?.id === characterId) {
                selectedCharacter.value = null;
                selectedSession.value = null;
                resetSessions();
            }
            
            ElMessage.success(t('characterDeleted'));
        }
    } catch (error) {
        console.error('Failed to delete character:', error);
        ElMessage.error(t('deleteError'));
    }
    isPromptViewDialogVisible.value = false;
};

// 创建成功处理
const handleCreateSuccess = (newCharacter) => {
    const formattedCharacter = {
        ...newCharacter,
        prompt_preview: newCharacter.prompt_preview || newCharacter.prompt || '',
        creator_id: newCharacter.creator_id || 1,
        chat_count: newCharacter.chat_count || 0
    };
    
    // 添加到角色列表
    characterSidebarRef.value?.addCharacter(formattedCharacter);
    
    // 选中新创建的角色
    selectedCharacter.value = formattedCharacter;
    selectedSession.value = null;
    resetSessions();
    
    // 加载新角色的聊天会话
    loadChatSessions(true);
    isCreateCharacterDialogVisible.value = false;
};

// 备注确认处理
const handleRemarkConfirm = async (newRemark) => {
    if (!currentEditingSession.value) return;
    
    try {
        // 调用API更新备注
        const response = await ApiCharacter.updateCharacterSessionRemark(String(currentEditingSession.value.id), newRemark);
        
        if (response && response.code === 200) {
            updateChatSession(currentEditingSession.value.id, { remark: newRemark });
            
            if (selectedSession.value && selectedSession.value.id === currentEditingSession.value.id) {
                selectedSession.value.remark = newRemark;
            }
            
            ElMessage.success(t('remarkUpdated'));
            currentEditingSession.value = null;
        } else {
            throw new Error('API response error');
        }
    } catch (error) {
        console.error('Failed to update remark:', error);
        ElMessage.error(t('updateError') || 'Failed to update remark');
    }
};

// 备注取消处理
const handleRemarkCancel = () => {
    currentEditingSession.value = null;
};

// 确认删除会话
const confirmDelete = async () => {
    deleteDialogVisible.value = false;

    if (sessionToDelete.value) {
        try {
            const response = await ApiCharacter.deleteCharacterSession(sessionToDelete.value.id);
            
            if (response && response.code === 200) {
                removeChatSession(sessionToDelete.value.id);
                if (selectedSession.value?.id === sessionToDelete.value.id) {
                    selectedSession.value = null;
                }

                ElMessage.success(t('sessionDeleted'));
            } else {
                throw new Error('API response error');
            }
        } catch (error) {
            console.error('Failed to delete session:', error);
            ElMessage.error(t('deleteError'));
        }
        
        sessionToDelete.value = null;
    }
};

// 处理消息更新事件
const handleSessionCreate = async (messageData) => {    
    const { sessionId, lastMessage, lastMessageTime, isNewSession } = messageData;
    
    // 截断过长的消息内容
    const truncatedMessage = lastMessage.length > 100 
        ? lastMessage.substring(0, 100) + '...' 
        : lastMessage;
    // 如果是新会话创建，需要处理临时会话转换
    if (isNewSession && selectedSession.value?.isNew) {
        selectedSession.value.id = messageData.sessionId;
        loadChatSessions(true);
        return;
    }
    
    // 更新会话信息
    updateChatSession(sessionId, {
        last_message_content: truncatedMessage,
        last_message_time: lastMessageTime
    });
    
    // 如果当前选中的是这个会话，更新选中状态
    if (selectedSession.value && selectedSession.value.id === sessionId) {
        selectedSession.value.last_message_content = truncatedMessage;
        selectedSession.value.last_message_time = lastMessageTime;
    }
};

// 处理模型变化
const handleModelSelected = async (modelName) => {
    let newSessionIndex = chatSessions.value.findIndex(session => session.isNew);
    if (currentModel.value && modelName && currentModel.value !== modelName) {
        if (newSessionIndex > -1) {
            chatSessions.value[newSessionIndex].ai_model = modelName;
            currentModel.value = modelName;
            if (selectedSession.value?.id != chatSessions.value[newSessionIndex].id) {
                selectedSession.value = chatSessions.value[newSessionIndex];
            }
            return;
        }

        handleCreateNewChat(modelName);
    }
    currentModel.value = modelName;
    if (newSessionIndex > -1) {
        chatSessions.value[newSessionIndex].ai_model = currentModel.value;
    }
};

const handleMessageUpdateNum = (messageData) => {
    const { sessionId, num } = messageData;
    const index = chatSessions.value.findIndex(session => session.id === sessionId);
    let count = 0;
    if(index > -1) {
        count = chatSessions.value[index].message_count;
    }
    updateChatSession(sessionId, { message_count: count + num });
};

// 处理快速填写（编辑功能）
const handleEdit = (characterData) => {
    try {
        // 从侧边栏的角色数组中查找完整的角色数据
        let completeCharacterData = characterData;

        // 如果找到了完整的角色数据，使用它；否则使用传入的数据
        if (completeCharacterData) {
            quickFillCharacterData.value = {
                id: completeCharacterData.id,
                name: completeCharacterData.name,
                description: completeCharacterData.description,
                prompt: completeCharacterData.prompt || '',
                gender: completeCharacterData.gender,
                age: completeCharacterData.age,
                height: completeCharacterData.height,
                weight: completeCharacterData.weight,
                nationality: completeCharacterData.nationality,
                currentLocation: completeCharacterData.current_location,
                hometown: completeCharacterData.hometown,
                languages: completeCharacterData.language,
                culturalBackground: completeCharacterData.cultural_background,
                education: completeCharacterData.education,
                relationshipStatus: completeCharacterData.relationship_status,
                sensitiveTopics: completeCharacterData.sensitive_topics,
                interests: completeCharacterData.interests
            };
        } else {
            // 使用传入的数据
            quickFillCharacterData.value = {
                id: characterData.id,
                name: characterData.name || characterData.category,
                description: characterData.description,
                prompt: characterData.prompt || characterData.content || '',
                // 其他字段如果没有就留空，用户可以自己填写
            };
        }
        
        // 关闭详情弹窗
        isPromptViewDialogVisible.value = false;
        
        // 打开创建弹窗
        isCreateCharacterDialogVisible.value = true;
    } catch (error) {
        console.error('Failed to handle edit:', error);
        ElMessage.error(t('loadEditDataFailed') || 'Failed to load data for quick fill');
    }
};

// 新增：处理过滤条件变化
const handleFilterChange = (params) => {  
    console.log('Character list filter changed:', params);
    filterParams.value.model = params.modelName;
    if (selectedCharacter.value) {
        loadChatSessions(true);
    }
};

// 获取 ChatSidebar 中的 filterItems 数据
const getFilterItems = () => {
    if (chatSidebarRef.value) {
        return chatSidebarRef.value.getFilterItems();
    }
    return [];
};



</script>

<style scoped lang="scss">
.character-list-page {
    display: flex;
    width: 100%;
    height: var(--height-small-base-view);
    background-color: var(--bg-primary);
    overflow: hidden;
}

/* 弹层容器样式 */
.create-character-dialog-container,
.prompt-view-dialog-container,
.remark-dialog-container {
    position: absolute;
}
</style> 