<template>
    <div class="character-message-item" :class="{ 'user-message': isUser, 'ai-message': !isUser }">
        <!-- AI消息布局 -->
        <div v-if="!isUser" class="ai-message-layout">
            <div class="avatar-container">
                <div class="avatar ai-avatar">
                    <l-img :src="'/static/images/default_avatar.png'" w="32px" h="32px" />
                </div>
            </div>
            <div class="message-content">
                <!-- AI思考中状态 -->
                <div v-if="isAiThinking" class="message-bubble ai-bubble">
                    <lottie-vue path="/static/thinking.json" :loop="true" :autoplay="true" :width="pxToRem('30px')" :height="pxToRem('30px')" />
                </div>
                <!-- 正常AI消息 -->
                <template v-else>
                    <message-retry
                        v-if="messageStatus === MESSAGE_STATUS.FAILED"
                        :is-retrying="messageStatus === MESSAGE_STATUS.SENDING"
                        @onRetry="handleRetry"
                    />
                    <div v-else class="message-bubble ai-bubble">
                        <div class="message-text" v-html="formattedContent"></div>
                    </div>
                </template>

                <div v-if="!isAiThinking" class="message-time">{{ formatTime(timestamp) }}</div>
            </div>
        </div>

        <!-- 用户消息布局 -->
        <div v-else class="user-message-layout">
            <div class="message-content">
                <!-- 用户消息总是显示正常气泡 -->
                <div class="message-bubble user-bubble">
                    <div class="message-text">{{ content }}</div>
                </div>

                <div class="message-time">{{ formatTime(timestamp) }}</div>
            </div>
            <div class="avatar-container">
                <div class="avatar user-avatar">
                    <l-img :src="'/static/images/default_avatar.png'" w="32px" h="32px" />
                </div>
            </div>
        </div>
    </div>
</template>

<script setup>
import { computed } from 'vue';
import { useI18n } from 'vue-i18n';
import LImg from '@/components/l-img.vue';
import LottieVue from '@/components/lottie.vue';
import MessageRetry from '@/components/message/retry.vue';
import { MSG_ROLE_USER, MESSAGE_STATUS } from '@/types/msg';
import { pxToRem } from '@/utils/px-to-rem';

const { t } = useI18n();

const props = defineProps({
    content: {
        type: String,
        required: true
    },
    role: {
        type: String,
        required: true
    },
    timestamp: {
        type: [String, Date, Number],
        default: () => new Date()
    },
    isMarkdown: {
        type: Boolean,
        default: false
    },
    typing: {
        type: Boolean,
        default: false
    },
    isAiThinking: {
        type: Boolean,
        default: false
    },
    messageStatus: {
        type: String,
        default: MESSAGE_STATUS.SUCCESS
    },
    messageId: {
        type: [String, Number],
        required: true
    }
});

const emit = defineEmits(['onRetry']);

// 判断是否为用户消息
const isUser = computed(() => props.role === MSG_ROLE_USER);

// 格式化消息内容
const formattedContent = computed(() => {
    if (props.isMarkdown) {
        // 这里可以添加markdown解析逻辑
        return props.content.replace(/\n/g, '<br>');
    }
    return props.content.replace(/\n/g, '<br>');
});

// 处理重试事件
const handleRetry = () => {
    emit('onRetry', props.messageId);
};

// 格式化时间
const formatTime = (timestamp) => {
    if (!timestamp) return '';

    const date = new Date(timestamp);
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const messageDate = new Date(date.getFullYear(), date.getMonth(), date.getDate());

    const timeString = date.toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit',
        hour12: false
    });

    // 格式化为 mm/dd, yyyy hh:mm
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    const year = date.getFullYear();

    return `${month}/${day}, ${year} ${timeString}`;
};
</script>

